# La plus petite case de la planche : 63,13 x 53,13 millièmes,
# soit 12,50 x 14,98 mm. C'est elle qui commande la taille des chiffres.


def _poser_decor(c, x0, y0):
    """Grave la planche UNE FOIS par document, puis la tamponne.
    ⚠️ Aucune couleur n'est posée dans le tampon : il prend celle de la
    feuille, donc le même tampon sert aux dix couleurs de l'arc-en-ciel.
    ⚠️⚠️ La marque est posée SUR LE CANEVAS (getattr), jamais dans un
    dictionnaire indexé par id() : Python réutilise les id() libérés et le
    deuxième document sortirait cassé. C'est la méthode de AHE, MAKEMO,
    DRAGON D'OR et AREAREA."""
    nom = "OHANA10B18_DECOR"
    if not getattr(c, "_o1018_forme_faite", False):
        c.beginForm(nom, lowerx=0, lowery=0, upperx=FEUILLE_W, uppery=FEUILLE_H)
        p = c.beginPath()
        for contour in _DECOR.split("|"):
            i = 0
            n = len(contour)
            while i < n:
                cmd = contour[i]
                j = i + 1
                while j < n and contour[j] not in "mlc":
                    j += 1
                v = [float(x) for x in contour[i + 1:j].split(",")]
                if cmd == "m":
                    p.moveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                elif cmd == "l":
                    p.lineTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H)
                else:
                    p.curveTo(v[0] / 1000.0 * FEUILLE_W, FEUILLE_H - v[1] / 1000.0 * FEUILLE_H,
                              v[2] / 1000.0 * FEUILLE_W, FEUILLE_H - v[3] / 1000.0 * FEUILLE_H,
                              v[4] / 1000.0 * FEUILLE_W, FEUILLE_H - v[5] / 1000.0 * FEUILLE_H)
                i = j
            p.close()
        c.drawPath(p, stroke=0, fill=1)
        c.endForm()
        c._o1018_forme_faite = True
    c.saveState()
    c.translate(x0, y0)
    c.doForm(nom)
    c.restoreState()


def _gen_grille(rng):
    """Une grille : par plage, DEUX numéros différents, le petit en haut."""
    haut, bas = [], []
    for a, b in RANGES:
        x, y = sorted(rng.sample(range(a, b + 1), 2))
        haut.append(x)
        bas.append(y)
    return haut, bas


# ══ LA TAILLE DES CHIFFRES ═══════════════════════════════════════════
# ⚠️ Mesurée, pas choisie : chaque valeur de chaque plage imprimée dans sa
#    case à 600 dpi, avec le gras du contour, et les pixels de contact
#    comptés contre les traits de sa grille. Voir le LIS_MOI.
_T_CASE = 32.0
#       30 pt -> 0 contact
#       32 pt -> 0 contact          ← INSTALLÉ
#       33 pt -> 56 pixels
#       34 pt -> 921 pixels
_T_SERIE = 5.0          # le numéro de série, dans le bandeau gris
# ⭐⭐ 28/09 (sceau Maeva : « blanchi là où il y a le gris ») :
#    LES BANDEAUX SONT BLANCS. Sur sa planche ils sont gris clair —
#    mesuré 226/255 sur les dix-huit, soit un gris de 0,114 — mais elle
#    les veut blancs : moins de toner, et le mot « 10 BOULES » ressort
#    mieux. Le dessin du cadre et le texte ne bougent pas, seul le fond
#    part.
#    ⭐ UNE SEULE VALEUR POUR revenir en arrière : remettre
#       _FOND_BANDEAU = colors.Color(0.886, 0.886, 0.886)
_FOND_BANDEAU = None          # None = blanc, rien n'est posé
_RENTRE_BANDEAU = 0.4 * mm


# ⚠️⚠️ 28/09 — DEUX GRILLES IDENTIQUES DANS LA MEME RAME : LE VRAI RISQUE.
#    Ce jeu ne peut fabriquer que 12 762 815 625 grilles differentes. Dans une rame de
#    500 feuilles il y a 9 000 grilles : le calcul dit une chance sur 315.
#    Deux cartons identiques dans une salle, c'est deux gagnants en meme
#    temps sur le meme tirage.
#    ⭐ REMEDE : on garde en memoire, PENDANT TOUT LE DOCUMENT, les grilles
#      deja sorties, et on retire au sort tant qu'on retombe sur une
#      ancienne. Le document ne peut plus contenir deux grilles pareilles,
#      quelle que soit sa taille. Cout : quelques tirages de plus, invisible.
def _tirer(rng, deja):
    for _ in range(200):
        g = _gen_grille(rng)
        cle = tuple(g[0]) + tuple(g[1])
        if cle not in deja:
            deja.add(cle)
            return g
    return g


def _dessiner_feuille(c, x0, y0, grilles, series, couleur_hex, titre_jeu="",
                      telephone="", style="eco"):
    police_ch, gris_ch = _style_chiffres(style)
    col = colors.HexColor(couleur_hex)

    # le fond des bandeaux — blanc depuis le 28/09, donc rien à poser
    if _FOND_BANDEAU is not None:
        c.setFillColor(_FOND_BANDEAU)
        for cols, bandeau, rangs in GRILLES:
            bx = x0 + cols[0] / 1000.0 * FEUILLE_W + _RENTRE_BANDEAU
            bw = (cols[5] - cols[0]) / 1000.0 * FEUILLE_W - 2 * _RENTRE_BANDEAU
            by = y0 + FEUILLE_H - bandeau[1] / 1000.0 * FEUILLE_H
            bh = (bandeau[1] - bandeau[0]) / 1000.0 * FEUILLE_H - _RENTRE_BANDEAU
            c.rect(bx, by, bw, bh, stroke=0, fill=1)

    c.setFillColor(col)
    _poser_decor(c, x0, y0)

    def MX(v):
        return x0 + v / 1000.0 * FEUILLE_W

    def MY(v):
        return y0 + FEUILLE_H - v / 1000.0 * FEUILLE_H

    for gi, (cols, bandeau, rangs) in enumerate(GRILLES):
        haut, bas = grilles[gi]
        for ligne, vals in ((0, haut), (1, bas)):
            hy, by = rangs[ligne]
            for ci, n in enumerate(vals):
                cx = MX((cols[ci] + cols[ci + 1]) / 2.0)
                cy = MY((hy + by) / 2.0) - _T_CASE * 0.34
                if _sec:
                    _sec.chiffre_micro(c, n, cx, cy, _T_CASE, gris_ch, police_ch,
                                       epaisseur=_GRAS_TRAIT)
                else:
                    c.setFillColor(gris_ch)
                    c.setFont(police_ch, _T_CASE)
                    c.drawCentredString(cx, cy, str(n))
        # le numéro de série, dans le blanc à gauche du bandeau gris
        c.setFillColor(GRIS)
        c.setFont(POLICE, _T_SERIE)
        c.drawString(MX(cols[0]) + 1.0 * mm,
                     MY(bandeau[1]) + 1.0 * mm, "N° %06d" % series[gi])
        if telephone:
            c.drawRightString(MX(cols[5]) - 1.0 * mm,
                              MY(bandeau[1]) + 1.0 * mm, telephone[:18])
        # cadre de microtexte autour de CHAQUE grille : un carton découpé
        # reste protégé
        if _sec:
            try:
                _sec.cadre_micro(c, MX(cols[0]), MY(rangs[1][1]),
                                 MX(cols[5]) - MX(cols[0]),
                                 MY(bandeau[0]) - MY(rangs[1][1]),
                                 series[gi], retrait=0.7 * mm)
            except Exception:
                pass


def generer_pdf(nb_cartes=18, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", style="eco", evenement_id="", page_start=1):
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=A4, pageCompression=1)

    nb_cartes = max(1, min(int(nb_cartes), 10000))
    nb_pages = (nb_cartes + CARTES_PAGE - 1) // CARTES_PAGE

    rng = random.Random(962000 + int(serie_start))
    serie = int(serie_start)
    no_page = max(1, int(page_start))
    _deja = set()      # ⚠️ le sac des grilles deja sorties dans CE document

    for _ in range(nb_pages):
        if nom_evenement:
            c.setFillColor(colors.black); c.setFont(POLICE, 8)
            c.drawCentredString(PAGE_W / 2, PAGE_H - 4.2 * mm, nom_evenement)
        c.setFillColor(GRIS_CLAIR); c.setFont(POLICE, 5.5)
        c.drawRightString(PAGE_W - 5 * mm, PAGE_H - 4.2 * mm, "%03d" % no_page)

        grilles = [_tirer(rng, _deja) for _ in range(CARTES_PAGE)]
        series = [serie + k for k in range(CARTES_PAGE)]
        coul = (couleur_perso if (couleur and couleur_perso)
                else RAINBOW[(serie - 1) % len(RAINBOW)] if couleur else "#555555")
        _dessiner_feuille(c, MARGE_X, MARGE_Y, grilles, series, coul,
                          titre_jeu, telephone, style=style)
        serie += CARTES_PAGE
        c.showPage()
        no_page += 1

    c.save()
    buf.seek(0)
    return buf


